// 0.23.0: a mid-sized C# project spent hours in 02 because one LINQ to SQL
// designer file produced 3,929 UNKNOWN inventory rows and 2,324 more waited on
// policies nobody had decided. Generated files are now found mechanically and
// classified without a model; policy questions, a RULEBOOK coverage check and
// a per-construct trial run before the full survey.
import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import { prepare, fake } from './helpers.mjs';
import { safePath, atomicWrite, writeJSON, readJSON, readManifest, readGeneratedFiles, contextHash } from '../lib/core.mjs';
import { detectGeneratedFiles, generatedFilesCommand, pendingRegeneration, globRegex } from '../lib/generated.mjs';
import { policyQuestions, recordPolicy, rulebookCoverage } from '../lib/policy.mjs';
import { runSurvey, mergeSurvey, planSurvey } from '../lib/survey.mjs';
import { approve, runStage, translate } from '../lib/pipeline.mjs';
import { migrationStatus } from '../lib/status.mjs';
import { preparationCommand } from '../scripts/preparation_cli.mjs';

const write = (f, name, text) => atomicWrite(safePath(f.root, name), text);
function generatedProject(t, options) {
  const f = prepare(t, options);
  write(f, 'src/Data.dbml', '<Database Name="Shop" />\n');
  write(f, 'src/Data.designer.cs', '#pragma warning disable 1591\n//------\n// <auto-generated>\n//     This code was generated by a tool.\n// </auto-generated>\n//------\nnamespace Shop { public partial class DataContext {} }\n');
  write(f, 'src/api/user.pb.go', '// Code generated by protoc-gen-go. DO NOT EDIT.\npackage api\n');
  write(f, 'proto/user.proto', 'syntax = "proto3";\n');
  write(f, 'src/vendor/lib.js', 'var a=1;\n');
  write(f, '.gitattributes', '# vendored\nsrc/vendor/** linguist-generated\n*.png binary\n');
  write(f, 'src/Resources.resx', '<root />\n');
  write(f, 'src/Strings.cs', 'namespace Shop { class Strings {} }\n');
  write(f, 'src/Shop.csproj', '<Project>\n  <ItemGroup>\n    <Compile Include="Strings.cs"><AutoGen>True</AutoGen><DependentUpon>Resources.resx</DependentUpon></Compile>\n  </ItemGroup>\n</Project>\n');
  return f;
}

test('generated files are found by name, header, project declaration and .gitattributes, with their inputs', t => {
  const f = generatedProject(t);
  const found = Object.fromEntries(detectGeneratedFiles(f.root, f.config).map(e => [e.file, e]));
  assert.deepEqual(Object.keys(found).sort(), ['src/Data.designer.cs', 'src/Strings.cs', 'src/api/user.pb.go', 'src/vendor/lib.js']);
  assert.equal(found['src/Data.designer.cs'].input, 'src/Data.dbml');
  assert.ok(found['src/Data.designer.cs'].signals.includes('designer file name') && found['src/Data.designer.cs'].signals.includes('<auto-generated> header'));
  // A protoc output away from its .proto is matched by name only when the
  // .proto is under a source root; here it is not.
  assert.equal(found['src/api/user.pb.go'].input, null);
  assert.equal(found['src/Strings.cs'].input, 'src/Resources.resx');
  assert.deepEqual(found['src/vendor/lib.js'].signals, ['.gitattributes linguist-generated']);
  // Ordinary sources stay out.
  assert.ok(!found['src/math_ops.py']);
  assert.ok(globRegex('*.min.js').test('a/b/c.min.js') && !globRegex('/top.js').test('a/top.js') && globRegex('a/**/x.go').test('a/x.go'));
});

test('generated-files keeps decisions, refuses a regeneration it cannot honour, and switches back', t => {
  const f = generatedProject(t);
  const preview = generatedFilesCommand(f.root, f.config);
  assert.equal(preview.written, false);
  assert.ok(!fs.existsSync(safePath(f.root, 'migration/generated-files.json')), 'a preview writes nothing');
  const written = preparationCommand(f.root, f.config, 'generated-files', { write: true });
  assert.equal(written.translate, 4); assert.equal(written.regenerate, 0);
  assert.deepEqual(written.withoutInput, ['src/api/user.pb.go', 'src/vendor/lib.js']);
  assert.throws(() => generatedFilesCommand(f.root, f.config, { regenerate: 'src/Data.designer.cs' }), /needs --how/);
  assert.throws(() => generatedFilesCommand(f.root, f.config, { regenerate: 'src/vendor/lib.js', how: 'npm run build' }), /no generator input/);
  assert.throws(() => generatedFilesCommand(f.root, f.config, { regenerate: 'src/Data.designer.cs', how: 'x' }), /no manifest target/);
  assert.throws(() => generatedFilesCommand(f.root, f.config, { regenerate: 'src/Data.designer.cs', how: 'x', target: '../outside.cs' }));
  assert.throws(() => generatedFilesCommand(f.root, f.config, { regenerate: 'src/math_ops.py', how: 'x', target: 'ported/x.mjs' }), /not a detected generated file/);
  const how = 'dotnet ef dbcontext scaffold';
  generatedFilesCommand(f.root, f.config, { regenerate: 'src/Data.designer.cs', how, target: 'ported/Data.mjs' });
  // A new scan keeps the decision.
  const again = generatedFilesCommand(f.root, f.config, { write: true });
  const entry = again.entries.find(e => e.file === 'src/Data.designer.cs');
  assert.deepEqual([entry.action, entry.how, entry.target], ['regenerate', how, 'ported/Data.mjs']);
  assert.deepEqual(pendingRegeneration(f.root, f.config).map(e => e.target), ['ported/Data.mjs']);
  generatedFilesCommand(f.root, f.config, { translate: 'src/Data.designer.cs' });
  const back = readGeneratedFiles(f.root).find(e => e.file === 'src/Data.designer.cs');
  assert.equal(back.action, 'translate'); assert.equal(back.how, undefined);
  assert.deepEqual(pendingRegeneration(f.root, f.config), []);
  // A hand-edited record that breaks the rules is refused, not trusted.
  const record = readJSON(safePath(f.root, 'migration/generated-files.json'));
  record.files[0].action = 'regenerate';
  writeJSON(safePath(f.root, 'migration/generated-files.json'), record);
  assert.throws(() => readGeneratedFiles(f.root), /regenerate/);
});

test('a regenerated file leaves the manifest and holds build approval until its target exists', async t => {
  const f = generatedProject(t, { count: 1 });
  write(f, 'migration/manifest.tsv', 'source\ttarget\nsrc/math_ops.py\tported/math_ops.mjs\nsrc/Data.designer.cs\tported/Data.mjs\n');
  const map = readJSON(safePath(f.root, 'migration/review-dependencies.json'));
  map.dependencies['src/Data.designer.cs'] = [];
  writeJSON(safePath(f.root, 'migration/review-dependencies.json'), map);
  assert.equal(readManifest(f.root, f.config).length, 2, 'translated by default');
  const before = contextHash(f.root, f.config);
  generatedFilesCommand(f.root, f.config, { write: true });
  generatedFilesCommand(f.root, f.config, { regenerate: 'src/Data.designer.cs', how: 'dotnet ef dbcontext scaffold' });
  assert.equal(readGeneratedFiles(f.root).find(e => e.file === 'src/Data.designer.cs').target, 'ported/Data.mjs', 'the manifest target is used');
  assert.deepEqual(readManifest(f.root, f.config).map(u => u.source), ['src/math_ops.py']);
  assert.notEqual(contextHash(f.root, f.config), before, 'the decision is part of the approved inputs');
  await runStage(f.root, f.config, 'judge');
  approve(f.root, f.config, 'translation', 'Fixture authorizes these exact outputs');
  await translate(f.root, f.config, fake);
  const status = migrationStatus(f.root, f.config);
  assert.deepEqual(status.regeneration.map(e => e.target), ['ported/Data.mjs']);
  assert.ok(status.nextActions.some(a => /Regenerate 1 generated file/.test(a)));
  assert.ok(!status.nextActions.some(a => /approve build/.test(a)), 'build is not offered while a regeneration is pending');
  assert.throws(() => approve(f.root, f.config, 'build', 'Build the translated outputs'), /Regenerate first \(1 pending/);
  write(f, 'ported/Data.mjs', 'export class DataContext {}\n');
  approve(f.root, f.config, 'build', 'Regenerated data context present; build the outputs');
  assert.deepEqual(migrationStatus(f.root, f.config).regeneration, []);
});

test('the inventory survey classifies generated-file sites without a model and reports counts only', async t => {
  const f = generatedProject(t);
  Object.assign(f.config, { transientRetryDelayMs: 1 });
  writeJSON(safePath(f.root, 'migration/config.json'), f.config);
  generatedFilesCommand(f.root, f.config, { write: true });
  const census = 'migration/inventory-sites.tsv';
  write(f, census, 'file\tsymbol\tsource_construct\nsrc/math_ops.py\tdivide\tfloor division\nsrc/Data.designer.cs\tDataContext\tdata-query\nsrc/Data.designer.cs\tTable\tdata-query\n');
  const asked = [];
  const surveyor = async ({ unit, reviewInput }) => {
    const input = JSON.parse(reviewInput); asked.push(...input.sites.map(s => s.file));
    return { result: { schemaVersion: 1, kind: 'survey', survey: 'inventory', target: unit.target, items: input.sites.map(s => ({ ...s, classification: 'OWNED', target_translation: 'number', evidence: `${s.file}:2`, status: 'confirmed' })) }, requestedModel: 'm', observedModel: null };
  };
  await runSurvey(f.root, f.config, 'inventory', surveyor, { sitesFile: census });
  assert.deepEqual(asked, ['src/math_ops.py'], 'no surveyor sees a generated file');
  const merged = mergeSurvey(f.root, f.config, 'inventory', { sitesFile: census });
  assert.deepEqual(merged.generated, { detected: 4, files: 1, sites: 2, regenerate: 0, withoutInput: 2 });
  const inventory = fs.readFileSync(safePath(f.root, 'migration/inventory.tsv'), 'utf8');
  assert.match(inventory, /src\/Data\.designer\.cs\tDataContext\tdata-query\tGENERATED\t[^\t]*translate the file as ordinary code[^\n]*src\/Data\.designer\.cs:1-7 \(generated file:/);
  assert.equal((inventory.match(/\tUNKNOWN\t/g) ?? []).length, 0);
  // A census of generated files only still merges, with no surveyor call.
  write(f, census, 'file\tsymbol\tsource_construct\nsrc/Data.designer.cs\tDataContext\tdata-query\n');
  asked.length = 0;
  await runSurvey(f.root, f.config, 'inventory', surveyor, { sitesFile: census });
  assert.equal(asked.length, 0);
  assert.equal(mergeSurvey(f.root, f.config, 'inventory', { sitesFile: census }).generated.sites, 1);
});

test('survey run --trial tries a few sites per construct in its own store and reports UNKNOWN per construct', async t => {
  const f = generatedProject(t, { count: 3 });
  Object.assign(f.config, { transientRetryDelayMs: 1 });
  writeJSON(safePath(f.root, 'migration/config.json'), f.config);
  generatedFilesCommand(f.root, f.config, { write: true });
  const census = 'migration/inventory-sites.tsv';
  write(f, census, 'file\tsymbol\tsource_construct\nsrc/math_ops.py\tdivide\tfloor division\nsrc/math_ops.py\tmod\tremainder\nsrc/text_ops.py\tlength\tlen()\nsrc/main.py\tmain\tlen()\nsrc/Data.designer.cs\tT\tdata-query\n');
  const surveyor = async ({ unit, reviewInput }) => {
    const input = JSON.parse(reviewInput);
    return { result: { schemaVersion: 1, kind: 'survey', survey: 'inventory', target: unit.target, items: input.sites.map(s => s.source_construct === 'len()'
      ? { ...s, classification: 'UNKNOWN', target_translation: 'TODO(port): RULEBOOK has no rule', evidence: `${s.file}:1`, status: 'unknown' }
      : { ...s, classification: 'OWNED', target_translation: 'number', evidence: `${s.file}:2`, status: 'confirmed' }) }, requestedModel: 'm', observedModel: null };
  };
  await assert.rejects(runSurvey(f.root, f.config, 'facts', surveyor, { trial: 2 }), /inventory survey only/);
  await assert.rejects(runSurvey(f.root, f.config, 'inventory', surveyor, { sitesFile: census, trial: 0 }), /from 1 to 50/);
  const report = await runSurvey(f.root, f.config, 'inventory', surveyor, { sitesFile: census, trial: 1 });
  const trialSites = fs.readFileSync(safePath(f.root, 'migration/surveys/inventory-trial/sites.tsv'), 'utf8').trim().split('\n').slice(1);
  assert.equal(trialSites.length, 3, 'one site per construct; the generated file is left out');
  assert.ok(trialSites.every(l => !l.startsWith('src/Data.designer.cs')));
  assert.deepEqual(report.trial.decide, ['len()']);
  assert.equal(report.trial.constructs.find(c => c.construct === 'len()').unknownRate, 1);
  assert.match(report.next, /Trial only: nothing was merged/);
  // The real survey store and the inventory are untouched.
  assert.ok(!fs.existsSync(safePath(f.root, 'migration/surveys/inventory/plan.json')));
  assert.ok(planSurvey(f.root, f.config, 'inventory', { sitesFile: census }).scopes.length >= 1);
  assert.match(fs.readFileSync(safePath(f.root, 'migration/inventory.tsv'), 'utf8'), /^file\tissue\tdecision/);
});

test('policy questions come from the source; answers go into one managed RULEBOOK block that coverage reads', t => {
  const f = generatedProject(t);
  write(f, 'src/Default.aspx', '<%@ Page Language="C#" %>\n');
  write(f, 'src/Default.aspx.cs', 'using System.Web.UI;\nclass P : Page { void L() { var u = Session["user"]; var d = DateTime.Now; } }\n');
  write(f, 'src/Repo.cs', 'using System.Data.Linq;\n');
  fs.writeFileSync(safePath(f.root, 'src/Legacy.cs'), Buffer.from([0x2f, 0x2f, 0x20, 0x93, 0xfa, 0x96, 0x7b, 0x0a]));
  generatedFilesCommand(f.root, f.config, { write: true });
  const { questions } = preparationCommand(f.root, f.config, 'policy-questions');
  const topics = questions.map(q => q.topic);
  for (const id of ['web-ui', 'data-access', 'session-state', 'date-time', 'generated.dbml', 'generated.resx']) assert.ok(topics.includes(id), id);
  assert.ok(!topics.includes('services') && !topics.includes('desktop-ui'), 'only topics the source uses');
  const web = questions.find(q => q.topic === 'web-ui');
  assert.ok(web.evidence.files >= 2 && web.options.at(-1).startsWith('Most conservative:'));
  assert.ok(!fs.existsSync(safePath(f.root, 'migration/surveys')), 'policy-questions writes nothing');
  const census = 'migration/inventory-sites.tsv';
  write(f, census, 'file\tsymbol\tsource_construct\nsrc/Default.aspx.cs\tSession\tweb-state\nsrc/Default.aspx.cs\tNow\tdatetime\nsrc/Repo.cs\tq\tdata-query\nsrc/Repo.cs\tq2\tdata-query\nsrc/math_ops.py\tdivide\tfloor division\nsrc/Data.designer.cs\tT\tdata-query\n');
  const first = rulebookCoverage(f.root, f.config, { sites: census });
  assert.equal(first.generatedSites, 1);
  assert.deepEqual(first.uncovered, ['data-query', 'datetime', 'floor division', 'web-state']);
  // A hand note inside the managed block survives every policy-record.
  write(f, 'migration/RULEBOOK.md', `${fs.readFileSync(safePath(f.root, 'migration/RULEBOOK.md'), 'utf8')}\n- floor division: keep Python semantics. construct: floor division\n<!-- code-migration-kit:policy:start -->\nTeam note: keep the old URL paths.\n<!-- code-migration-kit:policy:end -->\n`);
  assert.ok(!first.constructs.find(c => c.construct === 'floor division').covered, 'prose that only mentions a construct is not a rule');
  recordPolicy(f.root, f.config, { topic: 'data-access', answer: 'EF Core scaffolded from the database' });
  const auto = recordPolicy(f.root, f.config, { topic: 'date-time', answer: 'Keep local server time', auto: true });
  assert.match(auto.line, /auto mode chose the most conservative option: .*; TODO\(port\): confirm with the person/);
  recordPolicy(f.root, f.config, { topic: 'data-access', answer: 'Dapper with the same SQL' });
  const rulebook = fs.readFileSync(safePath(f.root, 'migration/RULEBOOK.md'), 'utf8');
  assert.match(rulebook, /^# Fixture rules/, 'the hand-written rules stay');
  assert.ok(rulebook.includes('Team note: keep the old URL paths.'), 'hand text inside the block stays');
  assert.equal(rulebook.match(/## Policy decisions/g).length, 1);
  // CRLF files and blank lines inside hand text survive as well.
  write(f, 'migration/RULEBOOK.md', rulebook.replace('Team note: keep the old URL paths.', 'Team note: keep the old URL paths.\n\n    code line').replace(/\n/g, '\r\n'));
  recordPolicy(f.root, f.config, { topic: 'configuration', answer: 'appsettings.json' });
  const crlf = fs.readFileSync(safePath(f.root, 'migration/RULEBOOK.md'), 'utf8');
  assert.equal(crlf.match(/## Policy decisions/g).length, 1);
  assert.match(crlf, /Team note: keep the old URL paths\.\r?\n\r?\n    code line/);
  assert.ok(crlf.includes('Dapper with the same SQL') && crlf.includes('[policy:configuration]'));
  assert.equal(rulebook.match(/code-migration-kit:policy:start/g).length, 1);
  assert.ok(rulebook.includes('Dapper with the same SQL') && !rulebook.includes('EF Core scaffolded'), 'a new answer replaces the old one');
  const second = rulebookCoverage(f.root, f.config, { sites: census });
  assert.deepEqual(second.uncovered, ['web-state']);
  assert.equal(second.constructs.find(c => c.construct === 'data-query').via, 'policy:data-access');
  assert.equal(second.constructs.find(c => c.construct === 'floor division').via, 'construct tag');
  assert.throws(() => recordPolicy(f.root, f.config, { topic: 'x y', answer: 'a' }), /topic/);
  assert.throws(() => recordPolicy(f.root, f.config, { topic: 'web-ui', answer: 'a\nb' }), /one line/);
});

test('detection does not flag hand-written files that only look generated', t => {
  const f = prepare(t);
  write(f, 'src/Program.cs', 'class Program {}\n');
  write(f, 'src/Form1.cs', 'class Form1 {}\n');
  write(f, 'src/Form1.Designer.cs', 'partial class Form1 {}\n');
  write(f, 'src/Form1.resx', '<root />\n');
  write(f, 'src/App.csproj', '<Project>\n  <ItemGroup>\n    <Compile Include="Program.cs" />\n    <Compile Include="Form1.Designer.cs"><AutoGen>True</AutoGen><DependentUpon>Form1.resx</DependentUpon></Compile>\n  </ItemGroup>\n</Project>\n');
  write(f, 'src/Reference.cs', 'class Reference {}\n');
  write(f, 'src/Lazy.cs', '// The code is generated lazily on first access.\nclass Lazy {}\n');
  write(f, 'src/UserProto.java', '// Generated by the protocol buffer compiler.  DO NOT EDIT!\n// source: user.proto\npackage x;\n');
  write(f, 'src/vendor/keep.js', 'var a;\n');
  write(f, 'src/vendor/lib.js', 'var b;\n');
  write(f, '.gitattributes', 'src/vendor/** linguist-generated\nsrc/vendor/keep.js -linguist-generated\n');
  const found = detectGeneratedFiles(f.root, f.config).map(e => e.file);
  assert.deepEqual(found.sort(), ['src/Form1.Designer.cs', 'src/UserProto.java', 'src/vendor/lib.js']);
});

test('a dropped or hand-edited regeneration is reported, never trusted', t => {
  const f = generatedProject(t);
  generatedFilesCommand(f.root, f.config, { write: true });
  generatedFilesCommand(f.root, f.config, { regenerate: 'src/Data.designer.cs', how: 'scaffold', target: 'ported/Data.mjs' });
  const record = readJSON(safePath(f.root, 'migration/generated-files.json'));
  record.files.find(e => e.file === 'src/Data.designer.cs').target = 'src/Data.designer.cs';
  writeJSON(safePath(f.root, 'migration/generated-files.json'), record);
  assert.throws(() => pendingRegeneration(f.root, f.config), /outside outputRoots|overlaps/);
  record.files.find(e => e.file === 'src/Data.designer.cs').target = 'ported/Data.mjs';
  writeJSON(safePath(f.root, 'migration/generated-files.json'), record);
  // The file stops looking generated: the next scan says which decision it dropped.
  write(f, 'src/Data.designer.cs', 'namespace Shop {}\n');
  fs.renameSync(safePath(f.root, 'src/Data.designer.cs'), safePath(f.root, 'src/DataContext.cs'));
  const rescan = generatedFilesCommand(f.root, f.config, { write: true });
  assert.deepEqual(rescan.droppedRegenerations, ['src/Data.designer.cs']);
  assert.match(rescan.next, /no longer detected as generated/);
});
